&#xa;   - &#xccad;&#xc18c;&#xd558;&#xba74;&#xc11c; &#xb3d9;&#xc791;&#xc2dc;&#xac04;, &#xacbd;&#xb85c; &#xb4f1; &#xb85c;&#xadf8;&#xb97c; &#xc800;&#xc7a5;&#xd558;&#xace0; &#xc774;&#xb97c; &#xc720;&#xc120; &#xb610;&#xb294; &#xbb34;&#xc120;&#xc73c;&#xb85c; PC&#xb098; &#xd3f0;&#xc73c;&#xb85c; &#xc804;&#xb2ec;&#xa;   - &#xc678;&#xbd80;&#xb9dd;(LTE &#xb4f1;)&#xc744; &#xc0ac;&#xc6a9;&#xd558;&#xc9c0; &#xbabb;&#xd568;&#xa;   - &#xbc30;&#xd130;&#xb9ac;&#xb294; &#xbd84;&#xb9ac;&#xd615;&#xc73c;&#xb85c; &#xc678;&#xbd80;&#xc5d0;&#xc11c; &#xad6c;&#xb9e4;&#xd574;&#xc11c;&#xb3c4; &#xc0ac;&#xc6a9;&#xd560;&#xc218; &#xc788;&#xc5b4;&#xc11c;&#xba74; &#xd568;.&#xa;   - &#xd38c;&#xd504;&#xb97c; &#xc774;&#xc6a9;&#xd558;&#xc5ec; &#xc774;&#xb3d9;&#xc2dc; &#xbc43;&#xba38;&#xb9ac;&#xc5d0; &#xc758;&#xd574;&#xc11c; &#xc77c;&#xc5b4;&#xb098;&#xb294; &#xd30c;&#xace0;&#xc5d0; &#xc758;&#xd574; &#xc774;&#xbb3c;&#xc9c8;&#xb4e4;&#xc774; &#xd37c;&#xc9c0;&#xc9c0; &#xc54a;&#xac8c; &#xd761;&#xc785;&#xd558;&#xb294; &#xad6c;&#xc870;&#xc600;&#xc5b4;&#xba74; &#xd568;&#xa;3. &#xc81c;&#xc548;&#xc11c;(&#xc0ac;&#xc591;, &#xac00;&#xaca9;, &#xae30;&#xac04;&#x2026;.)&#xc11c;&#xb294; 5&#xc6d4;&#xcd08; &#xc5f0;&#xd734; &#xb05d;&#xb098;&#xb294; &#xbc14;&#xb85c; &#xbcfc;&#xc218; &#xc788;&#xb3c4;&#xb85d; &#xc804;&#xb2ec; &#xbd80;&#xd0c1;&#xa;   - &#xacbd;&#xc7c1;&#xc785;&#xcc30;&#xbc29;&#xc2dd;&#xc73c;&#xb85c; &#xacb0;&#xc815;&#xacfc; &#xacc4;&#xc57d;&#xae4c;&#xc9c0; 2~3&#xac1c;&#xc6d4; &#xc608;&#xc815;, 5&#xc6d4;&#xc911; &#xc62c;&#xb9ac;&#xac8c; &#xb418;&#xba74; 7,8&#xc6d4;&#xc5d0; &#xacc4;&#xc57d;&#xc608;&#xc815;   &#xcd94;&#xac00;&#xc0ac;&#xd56d;&#xa;   - 3&#xb144;&#xc804; &#xd504;&#xb791;&#xc2a4; &#xae30;&#xc5c5;&#xc774; &#xbe44;&#xc2b7;&#xd55c; &#xac83;&#xc744; &#xc8fc;&#xbb38;&#xd558;&#xb824;&#xace0; &#xd588;&#xb294;&#xb370; 8&#xcc9c;&#xb9cc;&#xc6d0;&#xc774;&#xb77c;&#xb294; &#xac00;&#xaca9;&#xc73c;&#xb85c; &#xd3ec;&#xae30;&#xd588;&#xb2e4;&#xace0; &#xd568;&#xa;   - &#xae40;&#xc120;&#xc784;&#xc758; &#xac1c;&#xc778; &#xc0