<node CREATED="1777729578328" ID="ID_1484445848" MODIFIED="1777808941241" TEXT="-- &#xbb38;&#xc758; &#xc0ac;&#xd56d; --&#xa;1. &#xd604;&#xc7ac; &#xc0ac;&#xc6a9;&#xd558;&#xb294; &#xc2a4;&#xd0a4;&#xba38;&#xc5d0; &#xb300;&#xd55c; &#xc0ac;&#xc591; &#xc815;&#xbcf4;&#xb97c; &#xc54c;&#xc218; &#xc788;&#xc744;&#xae4c;&#xc694;?&#xa;&#xd604;&#xc7ac; &#xc720;&#xb7c9;&#xc740; &#xcd08;&#xb2f9; 1~2L &#xc218;&#xc900;&#xc73c;&#xb85c; &#xc0dd;&#xac01;&#xb418;&#xace0;, &#xc218;&#xb3d9;&#xc73c;&#xb85c; &#xc870;&#xc791;&#xd558;&#xace0; &#xc788;&#xc5b4; &#xd6a8;&#xc6a9;&#xc131;&#xc774; &#xb9e4;&#xc6b0; &#xb0ae;&#xc2b5;&#xb2c8;&#xb2e4;.  &#xc790;&#xccb4; &#xd14c;&#xc2a4;&#xd2b8;&#xb97c; &#xc218;&#xd589;&#xd574;&#xbcf8; &#xacb0;&#xacfc;, &#xd544;&#xd130;&#xb294; 10&#x3bc;m &#xc218;&#xc900;&#xc758; &#xd544;&#xd130;&#xbc31; &#xc0ac;&#xc6a9; &#xc2dc; &#xc801;&#xd569;&#xd55c; &#xac83;&#xc73c;&#xb85c; &#xd655;&#xc778;&#xd558;&#xc600;&#xc2b5;&#xb2c8;&#xb2e4;.&#xa;&#xa;2. &#xc9c0;&#xae08; &#xb610;&#xb294;  &#xd5a5;&#xd6c4;&#xc5d0; &#xad6c;&#xc870;&#xbb3c;&#xc774; &#xc124;&#xce58; &#xb420; &#xac00;&#xb2a5;&#xc131;&#xc774; &#xc788;&#xb294;&#xac00;&#xc694;?&#xa;&#xad6c;&#xc870;&#xbb3c; &#xc124;&#xce58;&#xb294; &#xacc4;&#xd68d;&#xb41c; &#xbc14; &#xc5c6;&#xc73c;&#xb098;, &#xc774;&#xb530;&#xae08; &#xc218;&#xc870;&#xc758; &#xbe48; &#xacf5;&#xac04;&#xc5d0; &#xbaa8;&#xd615;&#xc120;&#xc744; &#xb744;&#xc6b0;&#xb294; &#xb4f1; &#xb9e4;&#xd551; &#xc774;&#xd6c4; &#xac04;&#xd5d0;&#xc801;&#xc73c;&#xb85c; &#xc7a5;&#xc560;&#xbb3c;&#xc774; &#xcd94;&#xac00;&#xb418;&#xb294; &#xacbd;&#xc6b0;&#xac00; &#xc874;&#xc7ac;&#xd560; &#xc218; &#xc788;&#xc2b5;&#xb2c8;&#xb2e4;.&#xa;&#xa;3.  Lidar&#xb97c; &#xc0ac;&#xc6a9;&#xd560; &#xb9cc;&#xd07c; &#xc218;&#xc704;&#xbcc0;&#xd654;&#xac00; &#xc5c6;&#xb098;&#xc694;? &#xc218;&#xc704;&#xac00; &#xb192;&#xc544;&#xc838;&#xc11c; Lidar&#xb97c; &#xc0ac;&#xc6a9;&#xd560; &#xc218; &#xc5c6;&#xb294; &#xac00;&#xb2a5;&#xc131;&#xc740; &#xc5c6;&#xb098;&#xc694;?&#xa;&#xc790;&#xc5f0;&#xc801;&#xc778; &#xc99d;&#xbc1c;&#xb85c; &#xc778;&#xd574; &#xc218;&#xc704; &#xbcc0;&#xd654;&#xac00; &#xc788;&#xc744; &#xc218; &#xc788;&#xc73c;&#xb098;, &#xacfc;&#xb2e4; &#xc99d;&#xbc1c; &#xc2dc; &#xc815;&#xae30;&#xc801;&#xc73c;&#xb85c; &#xcda9;&#xc218;(&#x5145;&#x6c34;)&#xd558;&#xc5ec; &#xc77c;&#xc815; &#xc218;&#xc704;&#xb97c; &#xc720;&#xc9c0;&#xd558;&#xace0; &#xc788;&#xc2b5;&#xb2c8;&#xb2e4;.  &#xc5ec;&#xb2f4;&#xc73c;&#xb85c;, &#xc77c;&#xc804;&#xc5d0; LiDAR &#xc13c;&#xc11c;&#xb97c; &#xd65c;&#xc6a9;&#xd574; &#xb9f5;&#xd551;&#xc744; &#xc2dc;&#xb3c4;&#xd574;&#xbcf8; &#xacbd;&#xd5d8;&#xc774; &#xc788;&#xb294;&#xb370;, &#xb178;&#xc774;&#xc988;&#xac00; &#xc801;&#xc740; &#xb192;&#xc740; &#xd574;&#xc0c1;&#xb3c4;&#xac00; &#xc720;&#xc9c0;&#xb428;&#xc744; &#xc815;&#xc131;&#xc801;&#xc73c;&#xb85c; &#xd30c;&#xc545;&#xd558;&#xc600;&#xc2b5;&#xb2c8;&#xb2e4; .&#xa;&#xa;4. &#xc785;&#xcc30;&#xc774; &#xb41c; &#xd6c4;, &#xb0a9;&#xd488; &#xc804;&#xae4c;&#xc9c0; &#xc0ac;&#xc774;&#xd2b8;&#xc5d0;&#xc11c; &#xc2dc;&#xc6b4;&#xc804;&#xc774; &#xac00;&#xb2a5;&#xd55c;&#xac00;&#xc694;?&#xa;&#xc0ac;&#xc804; &#xd611;&#xc758; &#xd558;&#xc5d0; &#xc2dc;&#xc6b4;&#xc804; &#xac00;&#xb2a5;&#xd558;&#xba70;, &#xae30;&#xc874; &#xc2e4;&#xd5d8; &#xc77c;&#xc815;&#xc758; &#xce94;&#xc2ac;&#xc774; &#xc5c6;&#xb294; &#xd55c; &#xd3c9;&#xc77c; &#xb2a6;&#xc740; &#xc800;&#xb141;(7~8&#xc2dc; &#xc774;&#xd6c4;) &#xd639;&#xc740; &#xc8fc;&#xb9d0;&#xc5d0; &#xac00;&#xb2a5;&#xd569;&#xb2c8;&#xb2e4;.  &#xc2e4;&#xd5d8; &#xc77c;&#xc815;&#xc774; &#xb0b4;&#xb144; &#xc0c1;&#xbc18;&#xae30;&#xae4c;&#xc9c0; &#xc774;&#xbbf8; &#xb300;&#xbd80;&#xbd84; &#xc9dc;&#xc5ec;&#xc9c4; &#xd0d3;&#xc5d0;, &#xc8fc;&#xac04;&#xc5d0;&#xb294; &#xc2dc;&#xc6b4;&#xc804;&#xc774; &#xc5b4;&#xb824;&#xc6b4; &#xc810; &#xc591;&#xd574; &#xbd80;&#xd0c1;&#xb4dc;&#xb9bd;&#xb2c8;&#xb2e4;. &#xa;&#xa;5. &#xc2a4;&#xcef4; &#xc2a4;&#xd0a4;&#xba38;&#xc758; &#xc6d0;&#xd558;&#xb294;  &#xd615;&#xd0dc;&#xac00; &#xc788;&#xc73c;&#xc2e0;&#xc9c0;&#xc694;?&#xa;&#xbbf8;&#xd305; &#xc911; &#xb9d0;&#xc500;&#xb4dc;&#xb9b0; &#xb0b4;&#xc6a9;&#xacfc; &#xac19;&#xc774; &#xd38c;&#xd504;&#xb85c; &#xc815;&#xd654;&#xb418;&#xc9c0; &#xc54a;&#xc740; &#xd761;&#xc218;&#xd558;&#xc5ec; &#xd544;&#xd130;&#xb97c; &#xd1b5;&#xd574; &#xc774;&#xbb3c;&#xc9c8;&#xc744; &#xac78;&#xb7ec;&#xb0b4;&#xace0;, &#xc815;&#xd654;&#xb41c; &#xbb3c;&#xc744; &#xb2e4;&#xc2dc; &#xbc30;&#xcd9c;&#xd558;&#xb294; &#xd615;&#xd0dc;&#xb97c; &#xd76c;&#xb9dd;&#xd569;&#xb2c8;&#xb2e4;.&#xa;&#xa;6. &#xc785;&#xcc30;&#xc870;&#xac74;&#xc5d0; &#xb300;&#xd558;&#xc5ec; &#xc54c;&#xace0; &#xc2f6;&#xb2c8;&#xb2e4;.&#xa;&#xc785;&#xcc30; &#xbc29;&#xc2dd;&#xc740; &#xc77c;&#xc885;&#xc758; &#xc81c;&#xd55c; &#xacbd;&#xc7c1;&#xc785;&#xcc30;&#xb85c;, &#xc0ac;&#xc804; &#xae30;&#xc220;&#xd611;&#xc758;&#xac00; &#xc644;&#xb8cc;&#xb41c; &#xc5c5;&#xccb4;&#xc5d0; &#xd55c;&#xd574; &#xacac;&#xc801; &#xbc0f; &#xc0ac;&#xc591; &#xc81c;&#xcd9c;&#xc744; &#xc694;&#xccad; &#xb4dc;&#xb9b4; &#xc608;&#xc815;&#xc785;&#xb2c8;&#xb2e4;.  &#xc77c;&#xc815; &#xae30;&#xd55c; &#xc774;&#xd6c4; &#xc81c;&#xcd9c;&#xd558;&#xc2e0; &#xc11c;&#xb958;&#xc5d0; &#xb300;&#xd574; &#xae30;&#xc220;&#xb825;/&#xac00;&#xaca9;&#xc5d0; &#xb300;&#xd574; &#xad00;&#xacc4;&#xc790;&#xb4e4;&#xacfc; &#xd568;&#xaed8; &#xc885;&#xd569;&#xc801;&#xc73c;&#xb85c; &#xd3c9;&#xac00;&#xd558;&#xc5ec; &#xcd5c;&#xc885; &#xacb0;&#xc815;&#xc774; &#xc774;&#xb8e8;&#xc5b4;&#xc9d1;&#xb2c8;&#xb2e4;."/>
